<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/PasswordAccessFixture.php';
use FMonitor2\Jobs\{JobsRuntimeConfiguration,JobHandlerRuntime,MariaDbJobQueue,MariaDbOutbox,OutboxDispatchScheduler};
$f=new PasswordAccessFixture();$w=$f->web;$saved=[];
try {
    $f->start();$browser=[];$form=$w->request('GET','/pilot/forgot-password',[],$browser);assertSameValue(200,$form['status'],'INTENDED_RED EMAIL-FIRST-PASSWORD-RECOVERY-001 recovery boundary available');
    foreach(['/pilot/first-password','/pilot/forgot-password','/pilot/reset-password']as$path){assertSameValue(405,$w->request('PUT',$path,[],$browser)['status'],'unsupported method');assertSameValue(400,$w->request('POST',$path,['_csrf'=>'wrong'],$browser)['status'],'bad csrf');}
    $owner=$f->owner();$f->now=new DateTimeImmutable('now',new DateTimeZone('UTC'));$id=$f->uuid();$owner->requestPasswordReset('ordinary.person@shlz.ru',$id,'192.0.2.1');
    // Production dispatch router and actual generic outbox, with only network replaced.
    $environment=$w->environment()+['FMONITOR_PASSWORD_RECOVERY_KEY'=>base64_encode(str_repeat('K',32)),'FMONITOR_PASSWORD_RECOVERY_KEY_ID'=>'fixture-v1','FMONITOR_PUBLIC_BASE_URL'=>'https://portal.example.test','FMONITOR_RUNTIME_ENV'=>'test','FMONITOR_SMTP_HOST'=>'127.0.0.1','FMONITOR_SMTP_PORT'=>'2525','FMONITOR_SMTP_ENCRYPTION'=>'tls','FMONITOR_SMTP_USERNAME'=>'fixture@shlz.ru','FMONITOR_SMTP_PASSWORD'=>'synthetic-mail-password','FMONITOR_SMTP_FROM_ADDRESS'=>'fixture@shlz.ru','FMONITOR_SMTP_FROM_NAME'=>'FMonitor','FMONITOR_SMTP_TIMEOUT_SECONDS'=>'1','FMONITOR_SMTP_VERIFY_PEER'=>'true'];
    foreach($environment as$key=>$value){$saved[$key]=getenv($key);putenv($key.'='.$value);}
    $queue=new MariaDbJobQueue($w->db,$w->p,null,null,['outbox.dispatch'=>[1]]);$outbox=new MariaDbOutbox($w->db,$w->p);$scheduler=new OutboxDispatchScheduler($outbox,$queue);assertSameValue(1,$scheduler->enqueuePending()['enqueued'],'committed reset scheduled');$job=$queue->claim(['workerId'=>'password-worker','batch'=>1])[0];
    $network=[];$r=JobHandlerRuntime::handle($job,JobsRuntimeConfiguration::fromEnvironment(),null,function(array$wire)use(&$network,$w):array{assertSameValue(0,(int)$w->db->query('SELECT @@in_transaction')->fetch_column(),'wire outside transaction');$network[]=$wire;return['status'=>'delivered','providerReference'=>'synthetic-smtp'];});
    assertSameValue('completed',$r['status'],'production dispatcher handles recovery template');assertSameValue(1,count($network),'one wire call');assertSameValue('ordinary.person@shlz.ru',$network[0]['to'],'non-FKR recipient supported');
    $again=JobHandlerRuntime::handle($job,JobsRuntimeConfiguration::fromEnvironment(),null,function()use(&$network){$network[]='unexpected';return['status'=>'delivered'];});assertSameValue('completed',$again['status'],'job replay succeeds');assertSameValue(1,count($network),'job replay no duplicate mail');
    assertSameValue(1,preg_match('/token=([A-Za-z0-9_-]{43})/',$network[0]['text'],$m),'delivered secret');$token=$m[1];
    foreach([$r,$again,$f->rows('fm2_outbox_intents'),$f->rows('fm2_outbox_attempt_events'),$f->rows('fm2_password_events')]as$value)assertSameValue(false,str_contains(json_encode($value,JSON_INVALID_UTF8_SUBSTITUTE),$token),'dispatcher no secret persistence/output');
    // Token corruption, mail-address changes and key failures never admit or send.
    $before=$f->snapshot();assertSameValue(null,$owner->passwordReset('malformed'),'malformed token');assertSameValue('invalid',$owner->resetPassword(str_repeat('Z',43),PasswordAccessFixture::PASSWORD,PasswordAccessFixture::PASSWORD)['status'],'invented token');assertSameValue($before,$f->snapshot(),'invalid token unchanged');
    $w->db->query("UPDATE {$w->p}fm2_pilot_users SET email='moved.person@shlz.ru' WHERE user_id=9401");assertSameValue(null,$owner->passwordReset($token),'email change invalidates link');$w->db->query("UPDATE {$w->p}fm2_pilot_users SET email='ordinary.person@shlz.ru' WHERE user_id=9401");
    $f->now=$f->now->modify('+1 hour');$badKey=$f->uuid();$owner->requestPasswordReset('other.person@shlz.ru',$badKey,'192.0.2.9');$w->db->query("UPDATE {$w->p}fm2_password_recovery_requests SET encrypted_token='invalid-ciphertext' WHERE request_id='".$w->db->real_escape_string($badKey)."'");$called=false;try{$owner->deliverPasswordReset($badKey,function()use(&$called){$called=true;return['status'=>'delivered'];});}catch(Throwable){}assertSameValue(false,$called,'corrupt envelope never sent');
    foreach(['email','version','expiry']as$cause){
        $f->now=$f->now->modify('+1 hour');$request=$f->uuid();$owner->requestPasswordReset('other.person@shlz.ru',$request,'192.0.2.40');
        if($cause==='email')$w->db->query("UPDATE {$w->p}fm2_pilot_users SET email='changed@shlz.ru' WHERE user_id=9403");
        if($cause==='version')$w->db->query("UPDATE {$w->p}fm2_pilot_users SET session_version=session_version+1 WHERE user_id=9403");
        if($cause==='expiry')$f->now=$f->now->modify('+1800 seconds');
        $called=0;$sender=function()use(&$called){$called++;return['status'=>'delivered'];};$outcome=$owner->deliverPasswordReset($request,$sender);assertSameValue(['permanent',0],[$outcome['status'],$called],'dispatch rechecks '.$cause);
        if($cause==='email')$w->db->query("UPDATE {$w->p}fm2_pilot_users SET email='other.person@shlz.ru' WHERE user_id=9403");
        $owner->deliverPasswordReset($request,$sender);assertSameValue(0,$called,'terminal ineligible replay stays suppressed '.$cause);
    }
    // Concurrent quota admission: only one slot remains for two distinct requests.
    $f->now=$f->now->modify('+1 hour');$owner->requestPasswordReset('other.person@shlz.ru',$f->uuid(),'192.0.2.41');$f->now=$f->now->modify('+61 seconds');$owner->requestPasswordReset('other.person@shlz.ru',$f->uuid(),'192.0.2.41');$f->now=$f->now->modify('+61 seconds');$raceA=$f->uuid();$raceB=$f->uuid();$f->parallel([['method'=>'requestPasswordReset','arguments'=>['other.person@shlz.ru',$raceA,'192.0.2.41']],['method'=>'requestPasswordReset','arguments'=>['other.person@shlz.ru',$raceB,'192.0.2.41']]]);$ids=array_column($f->rows('fm2_password_recovery_requests'),'request_id');assertSameValue(1,(int)in_array($raceA,$ids,true)+(int)in_array($raceB,$ids,true),'atomic cooldown and quota admission');
    $trigger=$w->p.'outbox_request_fault';$w->db->query("CREATE TRIGGER $trigger BEFORE INSERT ON {$w->p}fm2_outbox_intents FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic outbox fault'");$before=$f->snapshot();$failed=false;try{$owner->requestPasswordReset($w->auth->email,$f->uuid(),'192.0.2.10');}catch(Throwable){$failed=true;}assertSameValue(true,$failed,'outbox fault propagated');assertSameValue($before,$f->snapshot(),'request/audit/outbox atomic rollback');$w->db->query("DROP TRIGGER $trigger");
    $w->stop();$w->start(extraEnvironment:['FMONITOR_PASSWORD_RECOVERY_KEY'=>'','FMONITOR_PASSWORD_RECOVERY_KEY_ID'=>'']);$admin=[];assertSameValue(303,$w->login($admin)['status'],'missing recovery config preserves normal login');$anon=[];$form=$w->request('GET','/pilot/forgot-password',[],$anon);if($form['status']===200){preg_match('/name="requestId" value="([^"]+)"/',$form['body'],$rid);$form=$w->request('POST','/pilot/forgot-password',['_csrf'=>$w->csrf($form['body']),'requestId'=>$rid[1]??$f->uuid(),'email'=>$w->auth->email],$anon);}assertSameValue(503,$form['status'],'missing recovery configuration visibly unavailable');assertSameValue(false,str_contains($form['body'],'SQLSTATE'),'safe configuration error');
    echo "PASS: EMAIL-FIRST-PASSWORD-RECOVERY-001 production dispatch and rejection/fault boundaries\n";
}finally{foreach($saved as$key=>$value)putenv($value===false?$key:$key.'='.$value);$f->close();}
